<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\LibraryBook;use App\Models\LibraryLoan;use App\Models\LibraryReservation;use App\Models\Student;use App\Notifications\ActivityNotification;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class LibraryController extends Controller { public function index(){return view('admin.library.index',['books'=>LibraryBook::withCount(['loans as borrowed_count'=>fn($q)=>$q->whereNull('returned_on')])->orderBy('title')->get(),'loans'=>LibraryLoan::with(['book','student'])->latest('borrowed_on')->get(),'students'=>Student::where('status','aktif')->orderBy('nama')->get(),'reservations'=>LibraryReservation::with(['book','student.user'])->where('status','waiting')->oldest()->get()]);} public function storeBook(Request $r){LibraryBook::create($r->validate(['code'=>['required','string','max:50','unique:library_books,code'],'title'=>['required','string','max:200'],'author'=>['nullable','string','max:150'],'publisher'=>['nullable','string','max:150'],'stock'=>['required','integer','min:0']]));return back()->with('success','Buku ditambahkan.');} public function storeLoan(Request $r){$d=$r->validate(['library_book_id'=>['required',Rule::exists('library_books','id')],'student_id'=>['required',Rule::exists('students','id')],'borrowed_on'=>['required','date'],'due_on'=>['nullable','date','after_or_equal:borrowed_on']]);$book=LibraryBook::findOrFail($d['library_book_id']);if($book->available_stock<1)return back()->withErrors(['library_book_id'=>'Stok buku tidak tersedia.'])->withInput();LibraryLoan::create($d);return back()->with('success','Peminjaman dicatat.');} public function returnLoan(Request $r,LibraryLoan $libraryLoan){$d=$r->validate(['returned_on'=>['required','date','after_or_equal:borrowed_on'],'fine'=>['nullable','numeric','min:0']]);$libraryLoan->update($d);$reservation=LibraryReservation::with('student.user')->where('library_book_id',$libraryLoan->library_book_id)->where('status','waiting')->oldest()->first();if($reservation){$reservation->update(['status'=>'available','expires_at'=>now()->addDays(2)]);if($reservation->student->user)$reservation->student->user->notify(new ActivityNotification(['title'=>'Buku tersedia','message'=>'Buku '.$libraryLoan->book->title.' tersedia untuk Anda sampai '.$reservation->expires_at->format('d M Y H:i').'.','url'=>route('student.library'),'type'=>'library']));}return back()->with('success','Pengembalian dicatat.');} }
